function throttle(func, limit) {
  let inThrottle = false; // Flag to track if ride is moving

  return function(...args) {
    const context = this;

    // 1. If not currently throttling, execute instantly
    if (!inThrottle) {
      func.apply(context, args);
      inThrottle = true; // Lock the gates

      // 2. Open the gates after the limit expires
      setTimeout(() => {
        inThrottle = false;
      }, limit);
    }
  };
}

// Usage:
const logScroll = throttle(() => {
  console.log('User is scrolling!');
}, 1000);

